def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_my = my[-1]
    last_opp = opp[-1]

    if n < 3:
        return 'C'

    # Count trailing opponent defections (consecutive D at end)
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_streak_d += 1
        else:
            break

    # Count trailing own defections
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            my_streak_d += 1
        else:
            break

    recent_win = 8 if n >= 8 else n
    recent_opp_d = sum(1 for i in range(n - recent_win, n) if opp[i] == 'D')
    recent_opp_c = recent_win - recent_opp_d

    opp_rate = opp_c / n

    # Detect pattern: opponent defected exactly 4 then went all C (four_D_ALLC signature)
    # i.e., first k moves D (k<=4) then all C since
    if n >= 8:
        # find first C index
        first_c = -1
        for i in range(n):
            if opp[i] == 'C':
                first_c = i
                break
        if first_c >= 1 and first_c <= 5:
            # all C after first_c
            all_c_after = True
            for i in range(first_c, n):
                if opp[i] == 'D':
                    all_c_after = False
                    break
            if all_c_after and first_c <= 5:
                return 'C'

    # Very cooperative opponent: stay cooperative, rarely probe
    if opp_rate >= 0.9 and opp_streak_d == 0:
        if n < 95 and n >= 12 and n % 30 == 0:
            return 'D'
        return 'C'

    # Mostly cooperative
    if opp_rate >= 0.75:
        if opp_streak_d >= 2:
            return 'D'
        return 'C'

    # Very defection-heavy: defect, with rare probe
    if opp_rate < 0.2:
        if n > 15 and opp_streak_d >= 6 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Last round: defect (no future retaliation matters)
    if n == 100 - 1:
        if opp_rate < 0.85:
            return 'D'
        return 'C'

    # If opponent just defected
    if last_opp == 'D':
        # Opponent defected right after many C's: likely punishment probe; retaliate once
        if last_my == 'C':
            return 'D'
        # We already defected too: avoid endless DD if opponent mostly cooperates
        if opp_rate > 0.6:
            # forgive occasionally to reduce DD lock
            if opp_streak_d <= 2 and rng.random() < 0.5:
                return 'C'
            if opp_streak_d >= 3 and my_streak_d >= 3:
                if rng.random() < 0.55:
                    return 'C'
            return 'D'
        # Opponent mostly defects: keep defecting, occasional cooperate to reset
        if my_streak_d >= 4 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_my == 'D':
        # We defected, they still cooperated: reciprocate cooperation
        # (avoid getting stuck exploiting generous/allC too aggressively)
        if opp_rate > 0.7:
            # They're cooperative: exploit moderately in later rounds
            if n >= 80 and rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated: cooperate, occasional probe against very cooperative
    if recent_opp_d == 0 and n >= 80:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'
